//! Exact fragment programs embedded in ShipPhysics.java, in construction order.
pub(crate) const FILTER_DYNAMIC: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n\n            ivec2 coord = ivec2(gl_FragCoord.xy);\n\n            void main() {\n                uint state = texelFetch(in_mask_struts, coord, 0).x;\n                if (state == 0u || (state & 4u) != 0u)\n                    discard;\n            }\n            ";
pub(crate) const FORCES: &str = "\n            #version 150 core\n\n            out vec4 out_pos_vel;\n            out vec2 out_force;\n            out uvec4 out_mask;\n\n            uniform vec2 gravity = vec2(0, -9.81);\n            uniform float floorHeight = -1000;\n            uniform vec2 waveSize = vec2(20, 2.0);\n            uniform float time = 0;\n            uniform float deltaT = 0;\n            uniform float fps;\n            uniform int iter = 100;\n            uniform float u_strength = 1;\n            uniform float u_rigidity = 1;\n            uniform float u_dampening = 1;\n            uniform float u_drag = 1;\n            uniform float u_buoyancy = 1;\n\n            uniform sampler2D in_pos_vel;\n            uniform sampler2D in_force;\n            uniform usampler2D in_mask_struts;\n            uniform sampler2D in_mass_strength;\n\n            const float[8] displacements = float[8](\n                1, 1.41421356237,\n                1, 1.41421356237,\n                1, 1.41421356237,\n                1, 1.41421356237\n            );\n\n            const float AIR = 1.225;\n            const float WATER = 1025;\n\n\n            float water(const float xpos, const float time) {\n                float invWave = 3.141592 / waveSize.x;\n                return ((sin(xpos * invWave + time * .3) * .7 + sin(invWave * 3 * xpos - time) * .3) + 1) * .5 * waveSize.y;\n            }\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n                ivec2 s[8] = ivec2[8](\n                    tex + ivec2(1, 0),\n                    tex + ivec2(1, 1),\n                    tex + ivec2(0, 1),\n                    tex + ivec2(-1, 1),\n                    tex + ivec2(-1, 0),\n                    tex + ivec2(-1, -1),\n                    tex + ivec2(0, -1),\n                    tex + ivec2(1, -1)\n                );\n\n                uvec4 curDat = texelFetch(in_mask_struts, tex, 0);\n                uint otherMasks[8] = uint[8](\n                    texelFetch(in_mask_struts, s[0], 0).x,\n                    texelFetch(in_mask_struts, s[1], 0).x,\n                    texelFetch(in_mask_struts, s[2], 0).x,\n                    texelFetch(in_mask_struts, s[3], 0).x,\n                    texelFetch(in_mask_struts, s[4], 0).x,\n                    texelFetch(in_mask_struts, s[5], 0).x,\n                    texelFetch(in_mask_struts, s[6], 0).x,\n                    texelFetch(in_mask_struts, s[7], 0).x\n                );\n\n                vec4 posVel = texelFetch(in_pos_vel, tex, 0);\n                out_pos_vel = posVel;\n                vec4 otherPosVel[8] = vec4[8](\n                    texelFetch(in_pos_vel, s[0], 0),\n                    texelFetch(in_pos_vel, s[1], 0),\n                    texelFetch(in_pos_vel, s[2], 0),\n                    texelFetch(in_pos_vel, s[3], 0),\n                    texelFetch(in_pos_vel, s[4], 0),\n                    texelFetch(in_pos_vel, s[5], 0),\n                    texelFetch(in_pos_vel, s[6], 0),\n                    texelFetch(in_pos_vel, s[7], 0)\n                );\n\n                vec3 massStrength = texelFetch(in_mass_strength, tex, 0).wyz;\n                vec3 otherMassStrength[8] = vec3[8](\n                    texelFetch(in_mass_strength, s[0], 0).wyz,\n                    texelFetch(in_mass_strength, s[1], 0).wyz,\n                    texelFetch(in_mass_strength, s[2], 0).wyz,\n                    texelFetch(in_mass_strength, s[3], 0).wyz,\n                    texelFetch(in_mass_strength, s[4], 0).wyz,\n                    texelFetch(in_mass_strength, s[5], 0).wyz,\n                    texelFetch(in_mass_strength, s[6], 0).wyz,\n                    texelFetch(in_mass_strength, s[7], 0).wyz\n                );\n\n                uint struts = curDat.y;\n\n                vec2 force = texelFetch(in_force, tex, 0).xy;\n                float invMass = 1 / massStrength.x;\n                out_mask = curDat;\n                out_mask.w = 0u;\n                for (uint i = 0u; i < 8u; i++) {\n                    if ((struts & (1u << i)) != 0u) {\n                        vec4 diff = otherPosVel[i] - posVel;\n                        float soft = mix(1, 0.001, float((curDat.x | otherMasks[i]) & 1u));\n                        float b = 0.03 * fps * iter;\n                        vec3 curMassStrength = min(otherMassStrength[i], massStrength);\n                        float k = 25 * 30 * curMassStrength.x * b * u_rigidity;\n                        float f = (length(diff.xy) - displacements[i]) * k * soft;\n                        if (diff.xy != vec2(0))\n                            force += normalize(diff.xy) * f + b * u_dampening * diff.zw;\n                        float str = mix(curMassStrength.y, curMassStrength.z, float(f < 0));\n                        out_mask.yz &= uvec2(~(uint(abs(f) > str * u_strength * iter * fps) << i));\n                    }\n                }\n                float w = water(posVel.x, time);\n                float dw = (water(posVel.x, time - deltaT) - w) * fps / (1 - min(0, posVel.y / waveSize.y));\n                float density = mix(WATER, AIR, float(posVel.y >= w));\n                vec2 speed = posVel.zw + vec2(0, dw);\n                if (speed != vec2(0)) {\n                    force -= normalize(speed) * 0.5 * dot(speed, speed) * density * mix(0.01, 0.5, float(out_mask.z != 255u)) * u_drag;\n                }\n                force -= density * u_buoyancy * gravity;\n                out_force = force * invMass + gravity;\n            }\n                ";
pub(crate) const INTEGRATE: &str = "\n            #version 150 core\n\n            out vec4 out_pos_vel;\n\n            uniform float deltaT;\n            uniform float floorHeight;\n\n            uniform sampler2D in_pos_vel;\n            uniform sampler2D in_force;\n            uniform usampler2D in_mask_struts;\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n                vec4 posVel = texelFetch(in_pos_vel, tex, 0);\n                vec2 vel = texelFetch(in_force, tex, 0).xy * deltaT + posVel.zw;\n                float speedsq = 1 / (dot(vel, vel) + 1);\n                vec2 refl = vec2(speedsq, -speedsq) * vel;\n                vec2 deltaV = vel * deltaT;\n                float collision = (floorHeight - posVel.y) / deltaV.y;\n                if (isnan(collision) || collision < 0 || collision > 1) {\n                    collision = 1;\n                }\n                vec2 deltaP = mix(refl, vel, collision);\n                out_pos_vel = vec4(deltaP * deltaT + posVel.xy, mix(refl, vel, float(collision == 1)));\n                if (out_pos_vel.y < floorHeight) {\n                    out_pos_vel.y = (out_pos_vel.y - floorHeight) * 0.01 + floorHeight;\n                    out_pos_vel.z *= .5;\n                }\n            }\n        ";
pub(crate) const FILTER_PERMEABLE: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n\n            void main() {\n                uint state = texelFetch(in_mask_struts, ivec2(gl_FragCoord.xy), 0).x;\n                if (state == 0u || (state & 3u) != 0u)\n                    discard;\n            }\n            ";
pub(crate) const FILL_WATER: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n            uniform sampler2D in_pos_vel;\n            uniform sampler2D in_water;\n\n            out vec4 out_water;\n\n            uniform float time = 0;\n            uniform float DeltaT = 1;\n            uniform vec2 waveSize = vec2(20, 2.0);\n            uniform float u_buoyancy = 1;\n            uniform float u_inflow = 1;\n            uniform float u_flow = 1;\n            uniform vec2 gravity = vec2(0, -9.81);\n\n            const float AIR = 1.225;\n            const float WATER = 1025;\n            const float sixtieth = 1.0/60.0/60.0;\n\n\n            float water(const float xpos) {\n                float invWave = 3.141592 / waveSize.x;\n                return ((sin(xpos * invWave + time * .3) * .7 + sin(invWave * 3 * xpos - time) * .3) + 1) * .5 * waveSize.y;\n            }\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n                uvec3 state = texelFetch(in_mask_struts, tex, 0).xyz;\n                vec4 posVel = texelFetch(in_pos_vel, tex, 0);\n                out_water = texelFetch(in_water, tex, 0);\n                // 85u for only perpendicular\n                float h = -min(posVel.y - water(posVel.x), 0);\n                if ((state.x & 3u) != 0u) {\n                    out_water.x = h;\n                } else {\n                    if ((state.z & 255u) != 255u) {\n                        float diff = h - out_water.x;\n                        float newvel = sign(diff) * sqrt(2 * -gravity.y * abs(diff)) * DeltaT * u_inflow * u_flow * sixtieth;\n                        newvel = -min(-newvel, out_water.x);\n                        out_water.x += newvel;\n                    }\n                }\n            }\n            ";
pub(crate) const FLOW_WATER: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n            uniform sampler2D in_pos_vel;\n            uniform sampler2D in_water;\n\n            out vec4 out_water_out_1;\n            out vec4 out_water_out_2;\n            out vec4 out_water_vel_1;\n            out vec4 out_water_vel_2;\n\n            uniform vec2 gravity = vec2(0, -9.81);\n            uniform float deltaT;\n            uniform float u_funk = 1;\n            uniform float u_flow = 0.5;\n\n\n            const float[8] displacements = float[8](\n                1, 0.70710678118,\n                1, 0.70710678118,\n                1, 0.70710678118,\n                1, 0.70710678118\n            );\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n\n                uvec3 state = texelFetch(in_mask_struts, ivec2(gl_FragCoord.xy), 0).xyz;\n\n                ivec2 s[8] = ivec2[8](\n                    tex + ivec2(1, 0),\n                    tex + ivec2(1, 1),\n                    tex + ivec2(0, 1),\n                    tex + ivec2(-1, 1),\n                    tex + ivec2(-1, 0),\n                    tex + ivec2(-1, -1),\n                    tex + ivec2(0, -1),\n                    tex + ivec2(1, -1)\n                );\n\n                vec4 posVel = texelFetch(in_pos_vel, tex, 0);\n                vec4 otherPosVel[8] = vec4[8](\n                    texelFetch(in_pos_vel, s[0], 0),\n                    texelFetch(in_pos_vel, s[1], 0),\n                    texelFetch(in_pos_vel, s[2], 0),\n                    texelFetch(in_pos_vel, s[3], 0),\n                    texelFetch(in_pos_vel, s[4], 0),\n                    texelFetch(in_pos_vel, s[5], 0),\n                    texelFetch(in_pos_vel, s[6], 0),\n                    texelFetch(in_pos_vel, s[7], 0)\n                );\n\n                vec4 water = texelFetch(in_water, tex, 0);\n\n                float funk = 1 + u_funk * (water.x - 1);\n\n                float outWeight[8] = float[8](0,0,0,0,0,0,0,0);\n                float outWaterVel[8] = float[8](0,0,0,0,0,0,0,0);\n\n                float totalWeight = 0;\n                for (uint i = 0u; i < 8u; i++) {\n                    vec2 norm = otherPosVel[i].xy - posVel.xy;\n                    if (norm != vec2(0)) {\n                        norm = normalize(norm);\n                    }\n                    float wvel = dot(norm, water.zw);\n                    vec4 otherWater = texelFetch(in_water, s[i], 0);\n                    float pd = water.x - otherWater.x;\n                    float gd = posVel.y - otherPosVel[i].y;\n\n                    float pgd = pd + gd;\n\n                    float bvel = sign(pgd) * sqrt(-2 * gravity.y * abs(pgd));\n\n                    float outvel = max(wvel + funk * bvel, 0);\n\n                    float weight = outvel * displacements[i];\n                    outWeight[i] = weight;\n                    totalWeight += weight;\n                    outWaterVel[i] = outvel;\n                }\n\n                float normalFactor = 0;\n                if (totalWeight != 0) {\n                    // mul by parameters for increased or decreased flow.\n                    normalFactor = water.x * u_flow * deltaT / totalWeight;\n                }\n\n                for (uint i = 0u; i < 8u; i++) {\n                    outWeight[i] *= normalFactor;\n                }\n\n                for (uint i = 0u; i < 4u; i++) {\n                    out_water_out_1[i] = outWeight[i];\n                    out_water_vel_1[i] = outWaterVel[i];\n                }\n                for (uint i = 0u; i < 4u; i++) {\n                    out_water_out_2[i] = outWeight[i+4u];\n                    out_water_vel_2[i] = outWaterVel[i+4u];\n                }\n            }\n            ";
pub(crate) const TRANSPORT_WATER: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n            uniform sampler2D in_pos_vel;\n            uniform sampler2D in_water;\n\n            uniform sampler2D in_water_out_1;\n            uniform sampler2D in_water_out_2;\n            uniform sampler2D in_water_vel_1;\n            uniform sampler2D in_water_vel_2;\n\n            out vec4 out_water;\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n\n                uvec3 state = texelFetch(in_mask_struts, ivec2(gl_FragCoord.xy), 0).xyz;\n\n                ivec2 s[8] = ivec2[8](\n                    tex + ivec2(1, 0),\n                    tex + ivec2(1, 1),\n                    tex + ivec2(0, 1),\n                    tex + ivec2(-1, 1),\n                    tex + ivec2(-1, 0),\n                    tex + ivec2(-1, -1),\n                    tex + ivec2(0, -1),\n                    tex + ivec2(1, -1)\n                );\n\n                vec4 posVel = texelFetch(in_pos_vel, tex, 0);\n                vec4 otherPosVel[8] = vec4[8](\n                    texelFetch(in_pos_vel, s[0], 0),\n                    texelFetch(in_pos_vel, s[1], 0),\n                    texelFetch(in_pos_vel, s[2], 0),\n                    texelFetch(in_pos_vel, s[3], 0),\n                    texelFetch(in_pos_vel, s[4], 0),\n                    texelFetch(in_pos_vel, s[5], 0),\n                    texelFetch(in_pos_vel, s[6], 0),\n                    texelFetch(in_pos_vel, s[7], 0)\n                );\n\n                uvec4 otherMaskStruts[8] = uvec4[8](\n                    texelFetch(in_mask_struts, s[0], 0),\n                    texelFetch(in_mask_struts, s[1], 0),\n                    texelFetch(in_mask_struts, s[2], 0),\n                    texelFetch(in_mask_struts, s[3], 0),\n                    texelFetch(in_mask_struts, s[4], 0),\n                    texelFetch(in_mask_struts, s[5], 0),\n                    texelFetch(in_mask_struts, s[6], 0),\n                    texelFetch(in_mask_struts, s[7], 0)\n                );\n\n                vec4 water = texelFetch(in_water, tex, 0);\n                out_water = water;\n                out_water.zw *= out_water.x;\n\n                bool permeable = ((state.x & 2u) == 0u);\n                bool perm[8] = bool[8](\n                    permeable && (state.z & 1u) != 0u && (otherMaskStruts[0].x & 2u) == 0u,\n                    permeable && (state.z & 2u) != 0u && (otherMaskStruts[1].x & 2u) == 0u,\n                    permeable && (state.z & 4u) != 0u && (otherMaskStruts[2].x & 2u) == 0u,\n                    permeable && (state.z & 8u) != 0u && (otherMaskStruts[3].x & 2u) == 0u,\n                    permeable && (state.z & 16u) != 0u && (otherMaskStruts[4].x & 2u) == 0u,\n                    permeable && (state.z & 32u) != 0u && (otherMaskStruts[5].x & 2u) == 0u,\n                    permeable && (state.z & 64u) != 0u && (otherMaskStruts[6].x & 2u) == 0u,\n                    permeable && (state.z & 128u) != 0u && (otherMaskStruts[7].x & 2u) == 0u\n                );\n\n                vec4 outWater1 = texelFetch(in_water_out_1, tex, 0);\n                vec4 velWater1 = texelFetch(in_water_vel_1, tex, 0);\n\n                for(uint i = 0u; i < 4u; i++) {\n                    vec2 norm = otherPosVel[i].xy - posVel.xy;\n                    if (norm != vec2(0)) {\n\n                        norm = normalize(norm);\n                    }\n                    float outWeight = outWater1[i];\n                    if (perm[i]){\n                        float otherOutWeight = texelFetch(in_water_out_2, s[i], 0)[i];\n                        out_water.x -= outWeight;\n                        out_water.zw -= water.zw * outWeight;\n                        out_water.x += otherOutWeight;\n                        out_water.zw -= norm * texelFetch(in_water_vel_2, s[i], 0)[i] * otherOutWeight;\n                    } else {\n                        out_water.zw -= norm * velWater1[i] * outWeight;\n                    }\n                }\n\n                vec4 outWater2 = texelFetch(in_water_out_2, tex, 0);\n                vec4 velWater2 = texelFetch(in_water_vel_2, tex, 0);\n\n                for(uint i = 0u; i < 4u; i++) {\n                    vec2 norm = otherPosVel[i+4u].xy - posVel.xy;\n                    if (norm != vec2(0)) {\n                        norm = normalize(norm);\n                    }\n                    float outWeight = outWater2[i];\n                    if (perm[i+4u]){\n                        float otherOutWeight = texelFetch(in_water_out_1, s[i+4u], 0)[i];\n                        out_water.x -= outWeight;\n                        out_water.zw -= water.zw * outWeight;\n                        out_water.x += otherOutWeight;\n                        out_water.zw -= norm * texelFetch(in_water_vel_1, s[i+4u], 0)[i] * otherOutWeight;\n                    } else {\n                        out_water.zw -= norm * velWater2[i] * outWeight;\n                    }\n                }\n                if (out_water.x != 0) {\n                    out_water.zw /= out_water.x;\n                } else {\n                    out_water.zw = vec2(0);\n                }\n            }\n            ";
pub(crate) const UPDATE_MASS: &str = "\n            #version 150 core\n\n            //uniform usampler2D in_mask_struts;\n            uniform sampler2D in_water;\n            uniform sampler2D in_mass_strength;\n            uniform usampler2D in_mask_struts;\n            uniform float u_thickness = 0.95;\n            uniform float u_waterweight = 1;\n\n            out vec4 out_mass_strength;\n\n            const float AIR = 1.225;\n            const float WATER = 1025;\n\n            void main() {\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n                out_mass_strength = texelFetch(in_mass_strength, tex, 0);\n                out_mass_strength.w = mix(out_mass_strength.x, mix(AIR, WATER * mix(1, u_waterweight, float((texelFetch(in_mask_struts, tex, 0).x & 2u) == 0u)), clamp(texelFetch(in_water, tex, 0).x, 0, 1)), u_thickness);\n            }\n            ";
pub(crate) const FILTER_OCCUPIED: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n\n            void main() {\n                uint state = texelFetch(in_mask_struts, ivec2(gl_FragCoord.xy), 0).x;\n                if (state == 0u)\n                    discard;\n            }\n            ";
pub(crate) const REPAIR_MASK: &str = "\n            #version 150 core\n\n            uniform usampler2D in_mask_struts;\n\n            out uvec4 out_mask;\n\n            void main() {\n\n                ivec2 tex = ivec2(gl_FragCoord.xy);\n                ivec2 s[8] = ivec2[8](\n                    tex + ivec2(1, 0),\n                    tex + ivec2(1, 1),\n                    tex + ivec2(0, 1),\n                    tex + ivec2(-1, 1),\n                    tex + ivec2(-1, 0),\n                    tex + ivec2(-1, -1),\n                    tex + ivec2(0, -1),\n                    tex + ivec2(1, -1)\n                );\n\n                out_mask = texelFetch(in_mask_struts, tex, 0);\n                uint struts[8] = uint[8](\n                    texelFetch(in_mask_struts, s[0], 0).y,\n                    texelFetch(in_mask_struts, s[1], 0).y,\n                    texelFetch(in_mask_struts, s[2], 0).y,\n                    texelFetch(in_mask_struts, s[3], 0).y,\n                    texelFetch(in_mask_struts, s[4], 0).y,\n                    texelFetch(in_mask_struts, s[5], 0).y,\n                    texelFetch(in_mask_struts, s[6], 0).y,\n                    texelFetch(in_mask_struts, s[7], 0).y\n                );\n                for (uint i = 0u; i < 4u; i++) {\n                    out_mask.yz &= ~(((~struts[i]) >> 4u) & (1u << i));\n                }\n                for (uint i = 0u; i < 4u; i++) {\n                    out_mask.yz &= ~(((~struts[i + 4u]) & (1u << i)) << 4u );\n                }\n            }\n            ";
pub(crate) const MOVE: &str = "\n\n            #version 150 core\n\n            out vec4 out_pos_vel;\n\n            uniform vec2 u_mouse;\n\n            uniform sampler2D in_pos_vel;\n\n            void main() {\n                out_pos_vel = texelFetch(in_pos_vel, ivec2(gl_FragCoord.xy), 0);\n                out_pos_vel.xy += u_mouse;\n            }\n                ";

#[cfg(test)]
mod tests {
    #[test]
    fn all_original_physics_shader_literals_match_decompiled_source() {
        let original = std::fs::read_to_string(
            "../SS2/decompiled/com/wicpar/sinkingsimulator/ship/ShipPhysics.java",
        )
        .unwrap();
        for source in [
            super::FILTER_DYNAMIC,
            super::FORCES,
            super::INTEGRATE,
            super::FILTER_PERMEABLE,
            super::FILL_WATER,
            super::FLOW_WATER,
            super::TRANSPORT_WATER,
            super::UPDATE_MASS,
            super::FILTER_OCCUPIED,
            super::REPAIR_MASK,
            super::MOVE,
        ] {
            assert!(original.contains(&format!("{source:?}")));
        }
    }
}
